mapper.select:
SELECT ,j.plan_version_id,j.id plan_job_id, s.id plan_segment_id,a.id allocation_id,a.allocation_role,a.resource_id, s.start_at,s.end_at,s.release_at,s.release_qty, m.planned_qty member_qty,j.planned_qty job_qty FROM aps_plan_job j JOIN aps_plan_job_member m ON m.plan_job_id=j.id
JOIN aps_plan_segment s ON s.plan_job_id=j.id LEFT JOIN aps_plan_allocation a ON a.plan_segment_id=s.id WHERE j.plan_version_id=#{planVersionId} AND s.start_at < #{toAt} AND s.end_at > #{fromAt}
ORDER BY w.workshop_code,c.center_code,o.order_no,ol.line_no,t.task_code,s.segment_no,a.allocation_role,a.seat_no

SELECT ,ao.id occupancy_id,ao.resource_id,r.resource_type, ao.start_at,ao.end_at,m.planned_qty member_qty,j.planned_qty job_qty FROM aps_actual_occupancy ao JOIN aps_execution_run er ON er.id=ao.execution_run_id JOIN aps_plan_job j ON j.id=er.plan_job_id JOIN aps_plan_job_member m ON m.plan_job_id=j.id
JOIN aps_resource r ON r.id=ao.resource_id WHERE ao.status IN ('ACTIVE','COMPLETED','CORRECTION') AND NOT EXISTS (SELECT 1 FROM aps_actual_occupancy newer WHERE newer.correction_of_id=ao.id) AND ao.start_at < #{toAt} AND COALESCE(ao.end_at,#{toAt}) > #{fromAt}
ORDER BY ao.start_at,ao.id,m.member_no

SELECT ,COALESCE(correction.id,p.id) report_id, COALESCE(correction.reported_at,p.reported_at) occurred_at, COALESCE(correction.processed_qty,p.processed_qty) processed_qty, COALESCE(correction.rejected_qty,p.rejected_qty) rejected_qty, COALESCE(correction.scrap_qty,p.scrap_qty) scrap_qty, COALESCE(correction.transferred_qty,p.transferred_qty) transferred_qty FROM aps_production_report p LEFT JOIN aps_production_report correction ON correction.correction_of_id=p.id JOIN aps_plan_job_member m ON m.id=p.plan_job_member_id JOIN aps_plan_job j ON j.id=m.plan_job_id
WHERE p.report_type<>'CORRECTION' AND COALESCE(correction.reported_at,p.reported_at)>=#{fromAt} AND COALESCE(correction.reported_at,p.reported_at)<#{toAt}
ORDER BY occurred_at,report_id

SELECT ,qe.id event_id,qe.event_type, original.event_type original_event_type,qe.from_bucket,qe.to_bucket, qe.occurred_at,qe.quantity FROM aps_quantity_event qe JOIN aps_output_lot output ON output.id=qe.output_lot_id JOIN aps_task t0 ON t0.id=output.source_task_id JOIN aps_plan_job_member m ON m.task_id=t0.id JOIN aps_plan_job j ON j.id=m.plan_job_id AND j.id=( SELECT j2.id FROM aps_plan_job_member m2 JOIN aps_plan_job j2 ON j2.id=m2.plan_job_id WHERE m2.task_id=t0.id ORDER BY j2.created_at DESC,j2.id DESC LIMIT 1)
LEFT JOIN aps_quantity_event original ON original.id=qe.reversal_of_id WHERE qe.occurred_at>=#{fromAt} AND qe.occurred_at<#{toAt}
ORDER BY qe.occurred_at,qe.id
